-- SF_MES template 그리드 컬럼 다국어 등록
-- 범위: WeZonGrid dataField/headerText + 변환 예정 ax5 key/label
-- ax5 컬럼은 key→DataField, label→HeaderText로 정규화하며 후속 WeZonGrid 변환에서도 같은 GridName/DataField를 유지한다.
-- 동적 컬럼과 GUI/그리드 소유권 미확정 항목은 실행 대상에서 제외하고 인벤토리에 기록한다.
-- 주의: MES 기준 DB의 기존 grid_col/grid_col_lang 데이터와 사용자 컬럼 설정을 모두 삭제하고 정본으로 재구성한다.
-- 실행 전 기존 사용자 컬럼 설정의 백업 필요 여부를 확인한다.
-- grid_col 예상 키: 4007건
-- grid_col_lang 입력 키: 13634건(확보된 번역만)
-- 파괴적 초기화 확인과 실행 대상 검사는 000_run_i18n.sql에서 수행한다.

-- grid_col은 사용자 컬럼 설정과 번역 부모를 함께 가지므로 MES 정본 기준으로 전체 초기화 후 재등록한다.
TRUNCATE TABLE grid_col_lang, grid_col RESTART IDENTITY;

CREATE TEMP TABLE tmp_template_grid_col (
    module_name varchar(100) NOT NULL, template_key varchar(50) NOT NULL,
    grid_name varchar(50) NOT NULL, data_field varchar(50) NOT NULL,
    column_index integer NOT NULL, header_text varchar(50) NOT NULL,
    width integer, visible boolean NOT NULL, source_widget varchar(20) NOT NULL
) ON COMMIT DROP;


SELECT module_name, template_key, grid_name, data_field, column_index, data_field, header_text, width, visible, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM tmp_template_grid_col
ON CONFLICT ("ModuleName", "TemplateKey", "GridName", "Key")
WHERE "ModuleName" IS NOT NULL AND "TemplateKey" IS NOT NULL AND "GridName" IS NOT NULL AND "Key" IS NOT NULL
DO UPDATE SET
    "Index"=EXCLUDED."Index", "DataField"=EXCLUDED."DataField", "HeaderText"=EXCLUDED."HeaderText",
    "Width"=EXCLUDED."Width", "Visible"=EXCLUDED."Visible", "_modified"=CURRENT_TIMESTAMP;

CREATE TEMP TABLE tmp_template_grid_col_lang (
    module_name varchar(100) NOT NULL, template_key varchar(50) NOT NULL,
    grid_name varchar(50) NOT NULL, data_field varchar(50) NOT NULL,
    lang_code varchar(30) NOT NULL, disp_text varchar(500) NOT NULL
) ON COMMIT DROP;


SELECT gc.id, src.lang_code, src.disp_text, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM tmp_template_grid_col_lang src
JOIN grid_col gc ON gc."ModuleName"=src.module_name AND gc."TemplateKey"=src.template_key
 AND gc."GridName"=src.grid_name AND gc."DataField"=src.data_field
ON CONFLICT ("GridColumn_id", "LangCode")
WHERE "GridColumn_id" IS NOT NULL AND "LangCode" IS NOT NULL
DO UPDATE SET
    "DispText"=EXCLUDED."DispText", "_modified"=CURRENT_TIMESTAMP;
